#define MOD 1000000007LL

typedef long long ll;

static ll modpow(ll a, ll e){
    ll r = 1 % MOD;
    while(e){
        if(e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

static ll inv(ll x){
    return modpow(x, MOD - 2);
