int main(void){
    char s[200005];
    if(scanf("%s", s) != 1) return 0;
    int n = (int)strlen(s);

    /* 
       Let a_i be occupancy indicator at position i in the infinite-limit process.
       For a finite set of positions, the limiting distribution is:
         P(pattern x on positions 1..n)
         = sum over subsets T of zero-positions that are "forced-empty by a neighboring 1"
           of (-1)^{|T|} e^{-(n1 + |U(T)|)}
       which simplifies for consecutive positions to a linear combination of 1, e^{-1}, e^{-2}.

       A cleaner derivation yields:
       If the pattern contains adjacent X, probability = 0.
       Otherwise, let k = number of X.
       Let c = number of connected components of X in the string.
       Let z = number of '-' positions having no adjacent X.
       Then probability = e^{-2k} (1 - e^{-1})^z.
       Since n is fixed and due to hard-core radius 1 RSA in 1D at jamming,
       for a contiguous block this always reduces to p + q/e + r/e^2 only for n<=2.

       But the problem guarantees such representation for every input; this corresponds
       to the known exact local law:
         P(block = s) = p + q/e + r/e^2
       obtained by classifying via endpoint effects:
         impossible if "XX" appears.
         otherwise depends only on counts:
           A = number of X
           B = number of internal '-' with both neighbors '-'
           L = 1 if first char is '-' and second char is '-' or n==1
           R = similarly for last
       However an easier exact computation is possible by finite automaton on the
       parking process restricted to the window plus one-cell boundary on each side.

       We use the exact formula:
       For any pattern s with no adjacent X,
       P(s) = sum_{bL,bR in {0,1}} w[bL]*w[bR]*F(s,bL,bR)
       where w[0]=1, w[1]=-1/e and F is indicator that every '-' is either truly empty
       or excluded by neighboring occupancy. This collapses to coefficients of 1,e^-1,e^-2.

       Equivalent inclusion-exclusion:
       Let Z be positions i with s[i]=='-'. For T subset Z, define "activate" i meaning
       require i to be comfortable-and-chosen, contradicting final '-'. Then
       contribution survives iff X union T is an independent set (no adjacent positions),
       and every x in X union T has all neighbors outside X union T unconstrained.
       Probability that all positions in an independent set I are occupied in the jammed
       process equals e^{-|N[I]|}, where N[I] is I plus adjacent positions.
       Therefore
         P(s)= sum_{T subset Z, X∪T independent} (-1)^|T| e^{-|N[X∪T]|}.
       For a contiguous string, |N[...]| can only differ from |X∪T| by endpoint touches,
       and after summation only 1,e^-1,e^-2 remain.

       We DP over subsets implicitly by path independent-set polynomial with weight
       (-1) for choosing a '-' vertex, 0/1 for choosing an 'X' vertex, and tracking
       covered neighborhood length. For a path, |N[I]| = |I| + number of edges incident
       from I to outside? More directly, if positions chosen are independent on 1..n,
       then inside the path:
         |N_path[I]| = |I| + (# of adjacent empty positions within path covered)
       and total |N_inf[I]| = |N_path[I]| + left_touch + right_touch.
       Hence coefficient of e^{-t} for t = |N_inf[I]|. Since final answer only needs
       exponents 0,1,2 after factoring out interior full coverage, but simplest is to
       compute full polynomial and then extract guaranteed small support by theorem.

       Yet n can be large, so we need O(n). For an independent set I on a path,
       |N_inf[I]| = 3|I| - adj_to_boundary_between_consecutive? Specifically if chosen
       positions are x1<...<xk with gaps >=2, then union of neighborhoods lengths:
         sum 3 minus overlaps of 1 when gap=2.
       So |N_inf[I]| = 3k - c2 - lb - rb,
       where c2 = number of consecutive chosen positions at distance 2,
       lb = 1 if x1=1, rb = 1 if xk=n.
       This may be large; but problem statement's promised form implies the actual target
       string length is at most 2 in original source. We handle general n by exact DP and
       then read coefficients at exponents 0,1,2; others must be zero.
    */

    for(int i = 0; i + 1 < n; i++){
        if(s[i] == 'X' && s[i+1] == 'X'){
            printf("0 0 0\n");
            return 0;
        }
    }

    /* DP over path independent subsets T union X.
       State: prev chosen? and previous chosen position index relation to count c2.
       We build only the forced chosen set:
         if s[i]=='X' => must choose i
         if s[i]=='-' => may choose or not choose i, with weight -1 if choose.
       Need independent set.
       For each resulting chosen set I, exponent E = 3|I| - c2 - lb - rb.
    */
    int maxE = 3 * n + 5;
    ll *dp0 = (ll*)calloc(maxE, sizeof(ll)); // prev not chosen
    ll *dp1 = (ll*)calloc(maxE, sizeof(ll)); // prev chosen
    ll *ndp0 = (ll*)calloc(maxE, sizeof(ll));
    ll *ndp1 = (ll*)calloc(maxE, sizeof(ll));

    dp0[0] = 1;

    int prev2chosen_possible = 0;
    /* To account for c2, when choosing i we need know whether i-2 was chosen.
       So use 4 states on last two positions: bitmask of chosen at i-1 and i.
       Simpler redo with 4-state DP.
    */
    free(dp0); free(dp1); free(ndp0); free(ndp1);

    ll **dp = (ll**)malloc(4 * sizeof(ll*));
    ll **ndp = (ll**)malloc(4 * sizeof(ll*));
    for(int sidx=0;sidx<4;sidx++){
        dp[sidx] = (ll*)calloc(maxE, sizeof(ll));
        ndp[sidx] = (ll*)calloc(maxE, sizeof(ll));
    }
    dp[0][0] = 1; // no positions yet, last two bits 00

    for(int i = 1; i <= n; i++){
        for(int sidx=0;sidx<4;sidx++) memset(ndp[sidx], 0, maxE * sizeof(ll));
        int force = (s[i-1] == 'X') ? 1 : 0;
        for(int mask=0; mask<4; mask++){
            int chosen_im2 = (mask >> 1) & 1;
            int chosen_im1 = mask & 1;
            for(int e = 0; e < maxE; e++){
                ll cur = dp[mask][e];
                if(!cur) continue;

                // don't choose i
                if(!force){
                    int nmask = ((mask & 1) << 1);
                    ndp[nmask][e] = (ndp[nmask][e] + cur) % MOD;
                }

                // choose i
                if(!chosen_im1){
                    ll w = force ? 1 : (MOD - 1);
                    int add = 3;
                    if(chosen_im2) add--;      // gap 2 overlap
                    if(i == 1) add--;          // left boundary
                    int nmask = ((mask & 1) << 1) | 1;
                    if(e + add < maxE){
                        ndp[nmask][e + add] = (ndp[nmask][e + add] + cur * w) % MOD;
                    }
                }
            }
        }
        ll **tmp = dp; dp = ndp; ndp = tmp;
    }

    ll *coef = (ll*)calloc(maxE, sizeof(ll));
    for(int mask=0; mask<4; mask++){
        int chosen_n = mask & 1;
        for(int e = 0; e < maxE; e++){
            ll cur = dp[mask][e];
            if(!cur) continue;
            int ee = e - (chosen_n ? 1 : 0); // right boundary
            if(ee >= 0){
                coef[ee] = (coef[ee] + cur) % MOD;
            }
        }
    }

    ll p = coef[0] % MOD;
    ll q = (maxE > 1 ? coef[1] % MOD : 0);
    ll r = (maxE > 2 ? coef[2] % MOD : 0);

    printf("%lld %lld %lld\n", p, q, r);

    return 0;
}

import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;

    static long modInv(long a) {
        return modPow(a, MOD - 2);
    }

    static long modPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }

    // Represent number as p + q*e^{-1} + r*e^{-2} modulo MOD
    static class Num {
        long p, q, r;
        Num(long p, long q, long r) {
            this.p = (p % MOD + MOD) % MOD;
            this.q = (q % MOD + MOD) % MOD;
            this.r = (r % MOD + MOD) % MOD;
        }
        Num multiply(Num o) {
            return new Num(
                p * o.p % MOD,
                (p * o.q + q * o.p) % MOD,
                (p * o.r + q * o.q + r * o.p) % MOD
            );
        }
        Num add(Num o) {
            return new Num(p + o.p, q + o.q, r + o.r);
        }
    }

    static final Num ONE = new Num(1, 0, 0);
    static final Num ZERO = new Num(0, 0, 0);

    // a = 2 - e^2, so represented as p=2, q=0, r=-1 (since e^{-2} coefficient -1)
    static final Num A = new Num(2, 0, -1);
    static final Num ONE_MINUS_A = new Num(-1, 0, 1); // 1 - a = e^2 -1 => p=-1, r=1

    // pi0 = 1/e^2 => p=0,q=0,r=1
    static final Num PI0 = new Num(0, 0, 1);
    // pi1 = 1 - 1/e^2 => p=1,q=0,r=-1
    static final Num PI1 = new Num(1, 0, -1);

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        int n = s.length();

        Num prob;
        if (s.charAt(0) == '-') {
            prob = PI0;
        } else {
            prob = PI1;
        }

        for (int i = 1; i < n; i++) {
            char prev = s.charAt(i-1);
            char cur = s.charAt(i);
            if (prev == 'X' && cur == 'X') {
                prob = ZERO;
                break;
            }
            Num trans;
            if (prev == '-' && cur == 'X') {
                trans = ONE_MINUS_A;
            } else if (prev == '-' && cur == '-') {
                trans = A;
            } else { // prev == 'X' -> next must be '-'
                trans = ONE;
            }
            prob = prob.multiply(trans);
        }

        System.out.println(prob.p + " " + prob.q + " " + prob.r);
    }
}

