public class Main {
    static final long MOD = 1_000_000_007L;

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char)c);
                c = read();
            }
            return sb.toString();
        }
    }

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    static long inv(long x) {
        return modPow(x, MOD - 2);
    }

    // polynomial up to degree 2 in x = 1/e : a0 + a1 x + a2 x^2
    static class Poly {
        long[] a = new long[3];
        Poly() {}
        Poly(long c0, long c1, long c2) {
            a[0] = (c0 % MOD + MOD) % MOD;
            a[1] = (c1 % MOD + MOD) % MOD;
            a[2] = (c2 % MOD + MOD) % MOD;
        }
        static Poly add(Poly p, Poly q) {
            return new Poly((p.a[0] + q.a[0]) % MOD, (p.a[1] + q.a[1]) % MOD, (p.a[2] + q.a[2]) % MOD);
        }
        static Poly sub(Poly p, Poly q) {
            return new Poly((p.a[0] - q.a[0]) % MOD, (p.a[1] - q.a[1]) % MOD, (p.a[2] - q.a[2]) % MOD);
        }
        static Poly mulConst(Poly p, long c) {
            c %= MOD;
            if (c < 0) c += MOD;
            return new Poly(p.a[0] * c % MOD, p.a[1] * c % MOD, p.a[2] * c % MOD);
        }
        static Poly mulX(Poly p) { // multiply by x=1/e, truncate deg<=2
            return new Poly(0, p.a[0], p.a[1]);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
