                        if (i + j <= 2) {
                            prod.a[i + j] = (prod.a[i + j] + sideL.a[i] * sideR.a[j]) % MOD;
                        }
                    }
                }
                prod = Poly.mulConst(prod, weight);
                ans = Poly.add(ans, prod);
            }
        }

        System.out.println(ans.a[0] % MOD + " " + ans.a[1] % MOD + " " + ans.a[2] % MOD);
    }
}

