#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

long long inv(long long x) {
    return modpow(x, MOD - 2);
}

struct Rat {
    long long v;
    Rat(long long _v = 0) {
        v = (_v % MOD + MOD) % MOD;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    string s;
    cin >> N >> s;

    // Final occupancy process on the infinite line:
    // A site is occupied iff it was chosen before itself and its two neighbors
    // in a random priority ordering. Hence for a block pattern, probability is
    // determined only by local comparisons among positions within distance 2.
    //
    // For any finite set, assign i.i.d. continuous priorities U_i.
    // Site i is occupied iff U_i < U_{i-1}, U_i < U_i (trivial), U_i < U_{i+1}
    // among still-available process equivalently iff U_i is smaller than both neighbors.
    // In the final maximal independent set generated by random sequential adsorption
    // on a path, the exact local probability can be computed by integrating over
    // relative orders. For length N, it depends only on components of '-' between X's,
    // and simplifies to p + q/e + r/e^2.
    //
    // We use the known exact formula:
    // Let pattern be valid iff it has no adjacent X.
    // Probability = 0 otherwise.
    // For valid pattern, if we pad by outside unknowns, only the left and right ends
    // contribute e terms. Specifically:
    //   P(s) = sum over endpoint states from parking process.
    //
    // A convenient exact characterization uses gap probabilities on the infinite line:
    // For a finite interval, conditioned on the nearest occupied seats just outside,
    // filling inside is independent. The needed boundary weights are:
    //   A_k = probability a segment of k empty sites between two blocked ends ends in
    //         a specific maximal pattern = 1/k! count of recursive orders
    // and after summing over outside distances, the infinite-limit gives only 1,e^{-1},e^{-2}.
    //
    // We compute coefficients by dynamic programming on three boundary conditions:
    //   0: left outside not occupied adjacent to first seat (free)
    //   1: left outside occupied adjacent to first seat (blocked)
    // similarly on right.
    // For a segment, exact probability under random priorities on a finite augmented path
    // can be integrated via recursion:
    // choose minimum-priority vertex in currently free segment uniformly;
    // it becomes occupied, neighbors blocked, recurse on left/right subsegments.
    //
    // Let F[l][r][a][b] for substring s[l..r], with a/b indicating whether positions
    // just outside are blocked by occupied neighbors. This gives rational probabilities.
    // Then infinite-line limit is:
    //   P = P00 + (P10-P00)/e + (P01-P00)/e + (P11-P10-P01+P00)/e^2
    // where Pab are probabilities for the finite segment conditioned on outside-adjacent
    // occupancy indicators a,b. By symmetry of outside-gap lengths in the limit, the
    // weights are exactly 1, e^{-1}, e^{-2}.
    //
    // The recursion below computes Pab exactly as rationals modulo MOD.

    vector<vector<array<array<long long,2>,2>>> memo(N, vector<array<array<long long,2>,2>>(N));
    vector<vector<array<array<char,2>,2>>> vis(N, vector<array<array<char,2>,2>>(N));

    function<long long(int,int,int,int)> solve = [&](int l, int r, int lb, int rb) -> long long {
        if (l > r) return 1;
        if (vis[l][r][lb][rb]) return memo[l][r][lb][rb];
        vis[l][r][lb][rb] = 1;

        int len = r - l + 1;
        long long ans = 0;
        long long invlen = inv(len);

        for (int m = l; m <= r; ++m) {
            // m is the first chosen (minimum priority) among this active segment.
            // Then it must be occupied in final pattern.
            if (s[m] != 'X') continue;

            // neighbors of m inside segment must be '-'
            if (m - 1 >= l && s[m - 1] == 'X') continue;
            if (m + 1 <= r && s[m + 1] == 'X') continue;

            // If m at boundary and outside blocked, still okay; blocked means m cannot be occupied.
            if (m == l && lb) continue;
            if (m == r && rb) continue;

            // Left subsegment: [l .. m-2], right boundary blocked by occupied at m
            bool ok = true;
            if (m - 1 >= l && s[m - 1] != '-') ok = false;
            if (m + 1 <= r && s[m + 1] != '-') ok = false;
            if (!ok) continue;

            long long L = solve(l, m - 2, lb, 1);
            long long R = solve(m + 2, r, 1, rb);
            ans = (ans + invlen * L % MOD * R) % MOD;
        }

        // Also possible that first chosen seat in this active segment is incompatible,
        // yielding zero contribution automatically by omission.
        memo[l][r][lb][rb] = ans;
        return ans;
    };

    long long P00 = (N==0?1:solve(0, N-1, 0, 0));
    // clear memo for other boundary conditions because recursion depends on lb/rb in state already, no need
    long long P10 = (N==0?1:solve(0, N-1, 1, 0));
    long long P01 = (N==0?1:solve(0, N-1, 0, 1));
    long long P11 = (N==0?1:solve(0, N-1, 1, 1));

    // Coefficients of 1, e^{-1}, e^{-2}
    long long p = P00;
    long long q = (P10 + P01 - 2 * P00) % MOD;
    if (q < 0) q += MOD;
    long long r = (P11 - P10 - P01 + P00) % MOD;
    if (r < 0) r += MOD;

    cout << p % MOD << " " << q % MOD << " " << r % MOD << "\n";
    return 0;
}
